// Package cudagrammar constrains language model generation to JSON that
// conforms to a schema.
//
// [Compile] turns a schema into a [Grammar]; [Grammar.Match] starts a
// [Matcher], a pushdown automaton over the generated bytes. Given a view of a
// tokenizer's vocabulary, a matcher reports which token ids can continue the
// document ([Matcher.TokenMask]) or masks the logits of those that cannot
// ([Matcher.ApplyMask]).
//
// The supported schema subset is objects with fixed required properties,
// arrays, strings, numbers, integers, booleans, nulls, and enumerations of
// strings, nested to any depth. Any other schema keyword is an error from
// Compile rather than a constraint silently dropped.
//
// Masks are computed on the CPU. The name records where they are applied, in a
// sampler running on the device, not where they are built.
//
//	g, err := cudagrammar.CompileString(`{"type":"object","properties":{"n":{"type":"integer"}}}`)
//	if err != nil {
//		return err
//	}
//	m := g.Match()
//	for !m.Done() {
//		m.ApplyMask(vocab, logits)
//		m.Accept(vocab(sample(logits)))
//	}
//
// For multi-token speculative decoding, [Matcher.Save], [Matcher.Restore], and
// [Matcher.Rollback] rewind accepted transitions in O(1), while
// [Matcher.SpeculativeMasks] and [Matcher.CommitPrefix] build per-step
// [Bitmask] slices over a [Vocabulary] and roll back draft transitions before
// verification commits the accepted prefix.
package cudagrammar
